# MILP-based broadcast routing with Steiner tree formulation
# Strategy: Find minimum cost broadcast tree with relay nodes.
# Key insight: Tree routing allows intermediate nodes to forward data,
# reducing source egress pressure dramatically.
# Uses aggressive graph pruning + MILP with proper linearization.

import networkx as nx
import json
import os
import time
import math
from typing import Dict, List
from itertools import islice

def search_algorithm(src, dsts, G, num_partitions):
    import pulp
    from pulp import LpProblem, LpMinimize, LpVariable, lpSum, LpBinary, LpContinuous, LpInteger, PULP_CBC_CMD, value

    start_time = time.time()
    print(f"\n=== MILP Broadcast Tree v2 ===")
    print(f"Source: {src}, Destinations: {len(dsts)}, Partitions: {num_partitions}")

    TRANSFER_SIZE = 300  # GB
    VM_COST_PER_SEC = 0.00015  # $/second
    VM_LIMIT = 2  # VMs per region
    partition_size = TRANSFER_SIZE / num_partitions  # GB per partition
    total_data_bits = num_partitions * partition_size * 8  # Total Gb to send on each tree edge

    provider_egress = {'aws': 5, 'gcp': 7, 'azure': 16}
    provider_ingress = {'aws': 10, 'gcp': 16, 'azure': 16}

    def get_provider(node):
        return node.split(':')[0]

    # Prepare graph
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # === AGGRESSIVE GRAPH PRUNING ===
    candidate_nodes = set([src] + dsts)

    # Get top-k cheapest paths for each destination (limited paths)
    for dst in dsts:
        try:
            paths = list(islice(nx.shortest_simple_paths(h, src, dst, weight='cost'), 5))
            for path in paths:
                candidate_nodes.update(path)
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass

    # Add direct neighbors of src for relay
    for neighbor in h.successors(src):
        candidate_nodes.add(neighbor)

    # Add paths between destinations for relay
    for i, d1 in enumerate(dsts):
        for d2 in dsts[i+1:]:
            try:
                path = nx.dijkstra_path(h, d1, d2, weight='cost')
                candidate_nodes.update(path)
            except:
                pass

    # If still too many nodes, prune to most relevant
    MAX_NODES = 35
    if len(candidate_nodes) > MAX_NODES:
        # Score nodes by relevance
        essential = set([src] + dsts)
        non_essential = candidate_nodes - essential

        # Keep nodes that appear on cheapest paths most frequently
        node_freq = {}
        for node in non_essential:
            node_freq[node] = 0

        for dst in dsts:
            try:
                paths = list(islice(nx.shortest_simple_paths(h, src, dst, weight='cost'), 3))
                for path in paths:
                    for node in path:
                        if node in non_essential:
                            node_freq[node] = node_freq.get(node, 0) + 1
            except:
                pass

        # Also count destination-to-destination paths
        for i, d1 in enumerate(dsts):
            for d2 in dsts[i+1:]:
                try:
                    path = nx.dijkstra_path(h, d1, d2, weight='cost')
                    for node in path:
                        if node in non_essential:
                            node_freq[node] = node_freq.get(node, 0) + 1
                except:
                    pass

        sorted_non_essential = sorted(non_essential, key=lambda n: node_freq.get(n, 0), reverse=True)
        candidate_nodes = essential | set(sorted_non_essential[:MAX_NODES - len(essential)])

    print(f"Candidate nodes: {len(candidate_nodes)}")

    # Build subgraph
    subG = h.subgraph(candidate_nodes).copy()
    subG.remove_edges_from(list(subG.in_edges(src)))

    nodes_list = list(subG.nodes())
    edges_list = list(subG.edges())

    print(f"Subgraph: {len(nodes_list)} nodes, {len(edges_list)} edges")

    # Precompute adjacency
    out_edges = {node: [] for node in nodes_list}
    in_edges_map = {node: [] for node in nodes_list}
    for (u, v) in edges_list:
        out_edges[u].append((u, v))
        in_edges_map[v].append((u, v))

    # === MILP FORMULATION ===
    prob = LpProblem("BroadcastTree", LpMinimize)

    # Binary edge selection: y[u,v] = 1 if edge is in broadcast tree
    y = {}
    for (u, v) in edges_list:
        y[(u, v)] = LpVariable(f"y_{u}_{v}", 0, 1, cat=LpBinary)

    # Flow variables for connectivity (one commodity per destination)
    fl = {}
    for dst in dsts:
        fl[dst] = {}
        for (u, v) in edges_list:
            fl[dst][(u, v)] = LpVariable(f"f_{dst}_{u}_{v}", 0, 1, cat=LpContinuous)

    # Transfer time variable
    T = LpVariable("T", 0, cat=LpContinuous)

    # === OBJECTIVE ===
    # Egress cost: for each tree edge, all num_partitions go through
    egress_cost = lpSum([
        y[(u, v)] * (num_partitions * partition_size * subG[u][v]['cost'])
        for (u, v) in edges_list
    ])

    # Instance cost estimation - use upper bound for active nodes
    num_active_est = 1 + len(dsts) + 5  # rough upper bound for relay nodes
    instance_cost = T * (VM_COST_PER_SEC * VM_LIMIT * num_active_est)

    prob += egress_cost + instance_cost, "TotalCost"

    # === CONNECTIVITY CONSTRAINTS ===
    for dst in dsts:
        for node in nodes_list:
            out_fl = lpSum([fl[dst][e] for e in out_edges.get(node, [])])
            in_fl = lpSum([fl[dst][e] for e in in_edges_map.get(node, [])])

            if node == src:
                prob += out_fl - in_fl == 1, f"flow_{dst}_{node}"
            elif node == dst:
                prob += in_fl - out_fl == 1, f"flow_{dst}_{node}"
            else:
                prob += out_fl - in_fl == 0, f"flow_{dst}_{node}"

        # Flow only on tree edges
        for (u, v) in edges_list:
            prob += fl[dst][(u, v)] <= y[(u, v)], f"fe_{dst}_{u}_{v}"

    # === TIME CONSTRAINTS ===
    # Edge throughput: total_data_bits * y[u,v] <= T * throughput
    for (u, v) in edges_list:
        throughput = subG[u][v]['throughput']
        prob += total_data_bits * y[(u, v)] <= T * throughput, f"te_{u}_{v}"

    # Node egress: sum of outgoing tree edges * total_data_bits <= T * egress_limit
    for node in nodes_list:
        provider = get_provider(node)
        eg_lim = provider_egress[provider] * VM_LIMIT  # Gbps

        prob += lpSum([y[e] * total_data_bits for e in out_edges.get(node, [])]) <= T * eg_lim, f"eg_{node}"

    # Node ingress
    for node in nodes_list:
        if node == src:
            continue
        provider = get_provider(node)
        ig_lim = provider_ingress[provider] * VM_LIMIT  # Gbps

        prob += lpSum([y[e] * total_data_bits for e in in_edges_map.get(node, [])]) <= T * ig_lim, f"ig_{node}"

    # === SOLVE ===
    solver = PULP_CBC_CMD(msg=0, timeLimit=90, threads=4)
    prob.solve(solver)

    print(f"Solver status: {pulp.LpStatus[prob.status]}")
    print(f"Solve time: {time.time() - start_time:.2f}s")

    bc_topology = BroadCastTopology(src, dsts, num_partitions)

