    print(f"Time after graph prep: {time.time() - start_time:.2f}s")

    # ======= Steiner Tree MILP =======
    # For each partition k, we need a Steiner tree from src spanning all dsts.
    # Since all partitions are symmetric, we can solve for a FEW distinct tree patterns
    # and assign partitions to them.

    # Approach: Solve for partition groups. 
    # Let's have G groups, each group has some number of partitions following the same tree.
    # w[g] = number of partitions in group g
    # y[g][(u,v)] = 1 if edge (u,v) is used in group g's tree

    # For tractability with Steiner trees, we use a flow-based formulation:
    # For each group g and destination d, there must be a path from src to d using only edges in the tree
    # This means: for each (g,d), flow conservation with y[g] edges

    # To avoid quadratic terms (f[g,d,(u,v)] <= y[g,(u,v)]), we use big-M linearization

    # Actually, let's simplify: since the problem has num_partitions=10 typically,
    # let's solve per-partition directly but with the Steiner tree model.
    # Variables: y[k][(u,v)] = 1 if partition k uses edge (u,v) in its tree
    # For each partition k and destination d, there's a flow of 1 from src to d on y[k] edges

    # This has K * |E| binary variables + K * |D| * |E| continuous flow variables
    # With K=10, |E|~500, |D|~7: 5000 binary + 35000 continuous - should be tractable

    NUM_GROUPS = min(num_partitions, 4)  # Use groups to keep tractable

    prob = LpProblem("SteinerBroadcast", LpMinimize)

    # w[g] = number of partitions assigned to group g
    w = {}
    for g in range(NUM_GROUPS):
        w[g] = LpVariable(f"w_{g}", 1, num_partitions, cat=LpInteger)

    # Sum of group sizes = num_partitions
    prob += lpSum([w[g] for g in range(NUM_GROUPS)]) == num_partitions, "total_partitions"

    # y[g][(u,v)] = 1 if edge (u,v) is in group g's Steiner tree
    y = {}
    for g in range(NUM_GROUPS):
        y[g] = {}
