    z = {}
    for g in range(NUM_GROUPS):
        z[g] = {}
        for (u, v) in edges_list:
            z[g][(u, v)] = LpVariable(f"z_{g}_{u}_{v}", 0, num_partitions, cat=LpInteger)
            # Linearization constraints
            prob += z[g][(u, v)] <= w[g], f"z_ub1_{g}_{u}_{v}"
            prob += z[g][(u, v)] <= num_partitions * y[g][(u, v)], f"z_ub2_{g}_{u}_{v}"
            prob += z[g][(u, v)] >= w[g] - num_partitions * (1 - y[g][(u, v)]), f"z_lb_{g}_{u}_{v}"

    # n[(u,v)] = sum_g z[g][(u,v)]
    n = {}
    for (u, v) in edges_list:
