    num_active_est = 1 + len(dsts) + 3
    instance_cost = T * VM_COST_PER_SEC * num_active_est * VM_LIMIT

    prob += egress_cost + instance_cost, "TotalCost"

    # Connectivity constraints: for each group g and destination d,
    # there's a unit flow from src to d along the tree
    for g in range(NUM_GROUPS):
        for dst in dsts:
            for node in nodes_list:
                out_fl = lpSum([fl[g][dst][e] for e in out_edges.get(node, [])])
                in_fl = lpSum([fl[g][dst][e] for e in in_edges_map.get(node, [])])

                if node == src:
                    prob += out_fl - in_fl == 1, f"flc_{g}_{dst}_{node}"
                elif node == dst:
                    prob += in_fl - out_fl == 1, f"flc_{g}_{dst}_{node}"
                else:
                    prob += out_fl - in_fl == 0, f"flc_{g}_{dst}_{node}"

            # Flow can only use tree edges
            for (u, v) in edges_list:
                prob += fl[g][dst][(u, v)] <= y[g][(u, v)], f"fle_{g}_{dst}_{u}_{v}"

    # Edge capacity / time constraints
    for (u, v) in edges_list:
        throughput = subG[u][v]['throughput']
        prob += n[(u, v)] * partition_size * 8 <= T * throughput, f"ec_{u}_{v}"

