        prob += total_in <= T * ig_lim, f"ig_{node}"

    print(f"MILP size: {len(prob.variables())} vars, {len(prob.constraints)} constraints")
    print(f"Time before solve: {time.time() - start_time:.2f}s")

    # Solve
