    prob.solve(solver)

    print(f"Solver status: {prob.status} ({pulp.LpStatus[prob.status]})")
    if prob.status == 1:
        print(f"Objective: {value(prob.objective):.2f}")
        print(f"T: {value(T):.2f}s")
        for g in range(NUM_GROUPS):
